// Turn the fetched page into comparable text, find the last snapshot for
// this target, and decide whether this check actually needs the model.
//
// Three of the four outcomes are settled here without spending a call:
// a failed fetch, a first-ever observation, and a page whose text has not
// changed at all. The model is only worth paying for when the text differs
// and something has to judge whether the difference matters.

const TARGET = 'Quillbeck - pricing';
const MAX_SNAPSHOT = 45000;   // Google Sheets caps a cell at 50k characters

// Visible text only. Raw HTML would make every class-name tweak look like a
// change, and would cost roughly ten times the tokens.
function toText(html) {
  if (typeof html !== 'string') return '';
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<\s*br\s*\/?>/gi, '\n')
    .replace(/<\/(p|li|h[1-6]|div|tr|blockquote|article|section|footer|header)\s*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .split('\n')
    .map((line) => line.replace(/[ \t\u00a0]+/g, ' ').trim())
    .filter(Boolean)
    .join('\n');
}

// --- what did we just fetch? --------------------------------------------

let fetch_ok = true;
let fetch_error = '';
let new_text = '';

try {
  const probe = $('Fetch Pricing Page').first().json;
  if (!probe || probe.error) {
    fetch_ok = false;
    fetch_error = 'could not fetch the page: ' +
      (probe && probe.error ? String(JSON.stringify(probe.error)).slice(0, 180) : 'no response');
  } else {
    new_text = toText(probe.data ?? probe.body ?? '');
    if (!new_text) {
      fetch_ok = false;
      fetch_error = 'the page was fetched but contained no readable text';
    }
  }
} catch (err) {
  fetch_ok = false;
  fetch_error = 'the fetch node produced no output: ' + err.message;
}

// --- what did we see last time? -----------------------------------------

const history = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row && row.target && row.snapshot);

let last = null;
for (let i = history.length - 1; i >= 0; i--) {
  if (String(history[i].target).trim() === TARGET) { last = history[i]; break; }
}

const prev_text = last ? String(last.snapshot) : '';
const is_first = !last;

// --- does this need judgement? ------------------------------------------

let needs_model = false;
let verdict = null;

if (!fetch_ok) {
  verdict = {
    changed: true,
    change_type: 'check_failed',
    summary: 'The competitor pricing page could not be read on this check.',
    note: fetch_error,
  };
} else if (is_first) {
  verdict = {
    changed: false,
    change_type: 'none',
    summary: 'Baseline snapshot captured. Nothing to compare against yet.',
    note: 'baseline - first observation of this target',
  };
} else if (prev_text === new_text) {
  verdict = {
    changed: false,
    change_type: 'none',
    summary: 'No change to the page text.',
    note: 'page text identical to the last snapshot - no model call needed',
  };
} else {
  needs_model = true;
}

// Keep the previous snapshot if the fetch failed, so one bad check does not
// erase the baseline and make the next check look like a first run.
const snapshot = (fetch_ok ? new_text : prev_text).slice(0, MAX_SNAPSHOT);

return [{
  json: { target: TARGET, needs_model, verdict, prev_text, new_text, snapshot, fetch_ok },
}];

// Produce the log row, from either the model's verdict or the one that was
// already settled upstream without a model call.

const ALLOWED = ['price_change', 'plan_added', 'plan_removed', 'feature_change', 'none'];

function extractJson(text) {
  if (!text) return null;
  let t = String(text).trim();
  t = t.replace(/^```(?:json)?/i, "").replace(/```$/, "").trim();
  const start = t.indexOf('{');
  const end = t.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try { return JSON.parse(t.slice(start, end + 1)); } catch (err) { return null; }
}

const prep = $('Prepare Comparison').first().json;
let verdict;

if (!prep.needs_model) {
  verdict = prep.verdict;
} else {
  const parsed = extractJson($input.first().json.merged_response);

  if (!parsed) {
    // We know the page changed - the text differed - but not whether it
    // mattered. That is exactly when a human should look.
    verdict = {
      changed: true,
      change_type: 'check_failed',
      summary: 'The page changed, but the comparison could not be interpreted.',
      note: 'model response was not valid JSON',
    };
  } else {
    const type = ALLOWED.includes(String(parsed.change_type || '').trim())
      ? String(parsed.change_type).trim()
      : 'none';
    const changed = parsed.changed === true;
    const notes = String(parsed.confidence_notes || '').trim();

    verdict = {
      changed,
      change_type: changed ? type : 'none',
      summary: String(parsed.summary || '').trim() || 'No summary returned.',
      note: notes ? 'model uncertain: ' + notes : 'page text differed - judged by model',
    };
  }
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    target: prep.target,
    changed: verdict.changed,
    change_type: verdict.change_type,
    summary: verdict.summary,
    note: verdict.note,
    snapshot: prep.snapshot,
  },
}];

